StoresMinimal:
query StoresMinimal {
  stores { id name slug type domainName region isCatalogPublished publishing processing
           currencies { defaultCurrency } }
}

StoreGroups:
query StoreGroups($storeSlug: String!) {
  store(slug: $storeSlug) { id slug storeGroups { id name slug productIds heroProductId createdAt processing clonable tags } }
}

StoreGroup:
query StoreGroup($storeSlug: String!, $groupId: String!) {
  store(slug: $storeSlug) { id slug storeGroup(id: $groupId) { id name slug productIds heroProductId createdAt processing clonable tags } }
}

CheckGroupNameSlugAvailability:
query CheckGroupNameSlugAvailability($slug: String!, $name: String!, $storeSlug: String!) {
  checkGroupNameSlugAvailability(slug: $slug, name: $name, storeSlug: $storeSlug) { name slug }
}

ImageUpload:
mutation ImageUpload($file: Upload!, $imageUploadInput: ImageUploadInput!) {
  imageUpload(file: $file, imageUploadInput: $imageUploadInput) {
    id name filename ext type width height createdAt
  }
}

CloneGroup:
mutation CloneGroup($groupId: String!, $imageIds: [String!]!) {
  cloneGroup(groupId: $groupId, imageIds: $imageIds) { id type status storeSlug }
}

OperationTask:
query OperationTask($id: String!) {
  operationTask(id: $id) {
    id type status storeSlug createdAt startedProcessingAt finishedProcessingAt
    summary { total retryFailed notStarted inProgress succeeded partiallySucceeded failed
              partiallyFailed skipped canceled progress }
  }
}

UpdateStoreGroup:
mutation UpdateStoreGroup($input: UpdateStoreGroupInput!) {
  updateStoreGroup(input: $input) { id name slug productIds heroProductId createdAt processing clonable tags }
}

PublishCatalog:
mutation PublishCatalog($storeSlug: String!) {
  publishCatalog(storeSlug: $storeSlug) { id slug isCatalogPublished }
}

StoreGroupWithProducts:
query StoreGroupWithProducts($storeSlug: String!, $groupId: String!) {
  store(slug: $storeSlug) { id slug storeGroup(id: $groupId) { id name slug productIds heroProductId processing tags products { id name baseProductId } } }
}

StoreBulkPriceEditBaseProductFilters:
query StoreBulkPriceEditBaseProductFilters($storeSlug: String!, $page: Float!, $pageSize: Float!) {
  storeBaseFilters(storeSlug: $storeSlug) { storeSlug storeBaseProductsFilters(page: $page, pageSize: $pageSize) { values { key label } } }
}

UpdateStoreGroupProductOrder:
mutation UpdateStoreGroupProductOrder($input: UpdateStoreGroupProductOrderInput!) {
  updateStoreGroupProductOrder(input: $input) { id name slug productIds heroProductId processing tags }
}
